 recepciones:async()=>{const rows=await api('/recepciones');$('#content').innerHTML=header('Recepciones','Verificación contra OC y guía de remisión.','<button class="btn primary" id="newReceipt">+ Nueva recepción</button>')+`<div class="panel">${table([['Número','numero'],['Orden','orden_compra'],['Almacén','almacen'],['Guía','guia_remision'],['Estado','estado',badge],['Fecha','fecha_recepcion',date]],rows,r=>`<button class="btn secondary sm" data-receipt-detail="${key(r,'id_recepcion')}">Detalle</button>${key(r,'estado')==='BORRADOR'?`<button class="btn success sm" data-confirm-receipt="${key(r,'id_recepcion')}">Confirmar</button>`:''}<button class="btn warning sm" data-new-incident="${key(r,'id_recepcion')}">Incidencia</button>`)}</div>`;$('#newReceipt').onclick=receiptForm;$$('[data-confirm-receipt]').forEach(b=>b.onclick=()=>confirmAction(`/recepciones/${b.dataset.confirmReceipt}/confirmar`,'¿Confirmar esta recepción? El stock aumentará.','Recepción confirmada.'));$$('[data-new-incident]').forEach(b=>b.onclick=()=>incidentForm(b.dataset.newIncident));$$('[data-receipt-detail]').forEach(b=>b.onclick=()=>showReceiptDetail(b.dataset.receiptDetail))},
 requerimientos:async()=>{const rows=await api('/taller/requerimientos');$('#content').innerHTML=header('Requerimientos de Taller','Solicitudes digitales y seguimiento de atención.',has('REQUERIMIENTO_REGISTRAR')?'<button class="btn primary" id="newRequest">+ Nuevo requerimiento</button>':'')+`<div class="panel">${table([['Número','numero'],['Solicitante','solicitado_por'],['Placa','placa_unidad'],['Mantenimiento','tipo_mantenimiento'],['Prioridad','prioridad',badge],['Estado','estado',badge],['Fecha','creado_en',date]],rows,r=>`<button class="btn secondary sm" data-request-detail="${key(r,'id_requerimiento')}">Ver detalle</button>`)}</div>`;$('#newRequest')?.addEventListener('click',requestForm);$$('[data-request-detail]').forEach(b=>b.onclick=()=>showRequestDetail(b.dataset.requestDetail))},
 salidas:async()=>{const rows=await api('/salidas');$('#content').innerHTML=header('Salidas de almacén','Preparación, evidencia firmada y entrega.','<button class="btn primary" id="newExit">+ Preparar salida</button>')+`<div class="panel">${table([['Número','numero'],['Requerimiento','requerimiento'],['Almacén','almacen'],['Entregar a','entregada_a'],['Estado','estado',badge],['Preparación','fecha_preparacion',date]],rows,r=>`<button class="btn secondary sm" data-view-evidence="${key(r,'id_orden_salida')}">Ver evidencias</button>`+(key(r,'estado')==='PREPARADA'?`<button class="btn secondary sm" data-evidence="${key(r,'id_orden_salida')}">Evidencia</button><button class="btn success sm" data-confirm-exit="${key(r,'id_orden_salida')}">Confirmar</button>`:''))}</div>`;$('#newExit').onclick=exitForm;$$('[data-view-evidence]').forEach(b=>b.onclick=()=>showEvidence(b.dataset.viewEvidence));$$('[data-evidence]').forEach(b=>b.onclick=()=>evidenceForm(b.dataset.evidence));$$('[data-confirm-exit]').forEach(b=>b.onclick=()=>confirmAction(`/salidas/${b.dataset.confirmExit}/confirmar`,'¿Confirmar la entrega? Se descontará el stock.','Salida confirmada.'))},
 movimientos:async()=>{const rows=await api('/movimientos');$('#content').innerHTML=header('Movimientos de inventario','Kardex trazable de entradas, salidas y reversos.')+`<div class="panel">${table([['ID','id_movimiento'],['Producto','nombre'],['Almacén','almacen'],['Tipo','tipo',badge],['Cantidad','cantidad'],['Saldo anterior','saldo_anterior'],['Saldo nuevo','saldo_nuevo'],['Origen','origen_tipo'],['Fecha','fecha',date],['Estado','anulado',v=>badge(v?'ANULADO':'VIGENTE')]],rows,r=>!key(r,'anulado')&&['INGRESO','SALIDA'].includes(key(r,'tipo'))?`<button class="btn warning sm" data-cancel-move="${key(r,'id_movimiento')}">Solicitar anulación</button>`:'')}</div>${has('MOVIMIENTO_ANULAR')?'<div id="cancelRequests"></div>':''}`;$$('[data-cancel-move]').forEach(b=>b.onclick=()=>cancelMovementForm(b.dataset.cancelMove));if(has('MOVIMIENTO_ANULAR'))await renderCancellationRequests()},
 reportes:async()=>{const [stock,buys,exits]=await Promise.all([safe('/reportes/stock-bajo'),safe('/reportes/compras'),safe('/reportes/salidas')]);state.cache.reportes={stock,buys,exits};$('#content').innerHTML=header('Reportes operativos','Inventario, compras y salidas consolidadas.','<button class="btn secondary" id="exportReports">Descargar CSV</button>')+`<div class="report-grid"><div class="panel"><div class="panel-head"><h3>Alertas de stock</h3><span class="count-chip">${stock.length}</span></div>${table([['Código','codigo'],['Producto','nombre'],['Stock','stock_actual'],['Mínimo','stock_minimo'],['Nivel','nivel',badge]],stock)}</div><div class="panel"><div class="panel-head"><h3>Compras</h3><span class="count-chip">${buys.length}</span></div>${table([['Orden','numero'],['Proveedor','razon_social'],['Fecha','fecha_emision',date],['Estado','estado',badge],['Total','total',(v,r)=>money(v,key(r,'moneda'))]],buys)}</div><div class="panel full-span"><div class="panel-head"><h3>Salidas</h3><span class="count-chip">${exits.length}</span></div>${table([['Salida','numero'],['Requerimiento','requerimiento'],['Placa','placa_unidad'],['Entregado a','entregada_a'],['Estado','estado',badge],['Fecha','fecha_entrega',date]],exits)}</div></div>`;$('#exportReports').onclick=exportReports},
