   `<div class="panel">${table([['Nombre','nombre'],['Correo','correo'],['Teléfono','telefono'],['Rol','rol',badge],['Estado','activo',v=>badge(v?'ACTIVO':'INACTIVO')],['Creación','creado_en',date]],rows,r=>`<button class="btn secondary sm" data-user-role="${key(r,'id_usuario')}">Cambiar rol</button><button class="btn ${key(r,'activo')?'danger':'success'} sm" data-user-state="${key(r,'id_usuario')}" data-active="${!key(r,'activo')}">${key(r,'activo')?'Desactivar':'Activar'}</button>`)}</div>
   <div class="panel"><div class="panel-head"><h3>Permisos por rol</h3><span class="text-muted small">Los cambios se aplican al siguiente acceso del usuario.</span></div><div class="permission-grid">${Object.entries(groups).map(([role,ps])=>{const roleId=key(ps[0],'id_rol');return `<article><strong>${esc(role)}</strong><div class="permission-list">${ps.map(x=>{const active=key(x,'asignado')===true||key(x,'asignado')===1||key(x,'asignado')==='1',locked=role==='ADMINISTRADOR'&&key(x,'permiso')==='USUARIOS_ADMINISTRAR';return `<label class="permission-option"><input class="form-check-input" type="checkbox" data-role-permission="${roleId}" value="${key(x,'id_permiso')}" ${active?'checked':''} ${locked?'disabled':''}><span>${esc(key(x,'descripcion'))}</span></label>`}).join('')}</div><button class="btn primary sm" data-save-permissions="${roleId}">Guardar permisos</button></article>`}).join('')}</div></div>`;
